"edgar":{perd:[["surge","Repousse Edgar dès son atterrissage avec un Super préchargé, lui refusant les soins de ses coups de poing et dégageant l'espace pour enchaîner."],["doug","Tient plus longtemps qu'Edgar à bout portant car Self Service soigne à chaque attaque pendant que la résurrection de Doug punit un engagement total."],["jacky","Encaisse mieux que les coups de poing rapprochés d'Edgar et en renvoie une partie via Counter Crush à chaque plongeon engagé."],["shelly","Explose Edgar à bout portant avec une gerbe de plombs concentrée, sans lui laisser le temps de se soigner à coups répétés."],["chester","Explose Edgar à bout portant, ses séquences de cloches tardives concentrant plusieurs projectiles là où ses coups courts doivent porter."],["otis","Réduit Edgar au silence dès son arrivée, lui refusant à la fois ses attaques et les soins que ses poings lui rendraient pendant le duel."],["griff","Explose Edgar au corps à corps en concentrant chaque pièce, submergeant les soins de ses coups avant qu'ils ne stabilisent le duel."],["bull","Encaisse mieux qu'Edgar à bout portant, Tough Guy réduisant les dégâts de ses poings dès que Bull tombe bas en santé."],["stu","Déborde Edgar avec de rapides dashs Nitro Boost, rompant le contact avant que ses coups de poing courts ne lui rendent une santé utile."]],bat:[["barley","Saute sur Barley et submerge sa faible santé avec des coups de poing rapides qui le soignent, avant qu'il ne puisse fuir ou recharger."],["dynamike","Atterrit à côté de Dynamike avant que ses explosifs retardés ne détonent, tenant sous les explosions perdues grâce à des coups de poing rapides qui le soignent."],["grom","Réduit à néant l'espacement d'artillerie de Grom en sautant dans son dos, où ses faibles dégâts à bout portant ne dépassent pas des coups qui soignent."],["kit","Tient plus longtemps que Kit au contact, en utilisant Fisticuffs pour amplifier les soins de ses poings et punir son plongeon engagé."],["larry","Saute au-delà de la portée d'artillerie de Larry, puis des coups de poing soignants le submergent avant que ses explosions retardées ne détonent."],["lou","Se rapproche de Lou, puis l'explose et se soigne à bout portant avant que ses volées répétées n'accumulent du gel."],["mrp","Bondit au-delà du rideau de porteurs qui protège Mr P, atterrissant derrière lui pour submerger sa faible défense rapprochée."],["sprout","Franchit la Haie qui protège Sprout et réduit à néant sa distance d'artillerie, tenant sous les dégâts des Seed Bombs grâce à des coups de poing rapides."],["squeak","Franchit le contrôle de zone de Squeak d'un saut dans son dos, puis tient sous les explosions à retardement en enchaînant des coups rapides."],["ziggy","Atterrit à côté de Ziggy et submerge sa faible santé avec des coups de poing soignants rapides avant que l'éclair retardé ne frappe à proximité."]]},
