"emz":{perd:[["janet","Porte plus loin que sa zone de gerbe à dégâts maximum avec ses notes concentrées, pendant que son vol en jetpack échappe à son Super ralentissant sous pression."],["mortis","Plonge en ruée dans l'angle mort rapproché de son spray, où chaque nuage ne le touche qu'une fois avant qu'il ne l'explose."],["barley","La bombarde par-dessus les murs, hors de portée de sa riposte à la laque, la forçant à traverser des flaques persistantes pendant qu'il se soigne à chaque attaque."],["juju","Contrôle Emz par-dessus les murs avec des tirs élémentaires en cloche, pendant que Gris-Gris harcèle son angle mort et ralentit sa retraite."],["larry","Lance des attaques à double explosion par-dessus le couvert, hors de portée de sa gerbe, pendant que Lawrie presse l'angle mort rapproché. Faible aussi contre : Thrower"]],bat:[["chester","Cumule les dégâts de laque pendant que Chester approche, puis utilise Friendzoner pour le renvoyer dans le nuage persistant."],["leon","Contrôle l'approche de Leon avec de larges dégâts de spray, puis emploie Friendzoner pour le repousser hors de la portée où ses lames frappent le plus fort."],["piper","Punit Piper dès que le couvert raccourcit le couloir, cumulant les dégâts de gerbe là où ses tirs perdent une grande part de leur puissance."],["poco","Submerge les soins de Poco avec des dégâts de gerbe cumulés lorsque ses coéquipiers proches se regroupent dans le même nuage."],["rico","Presse Rico à travers les murs avec Acid Spray tout en évitant les angles de rebond que ses projectiles contrôlent."],["rosa","Punit l'approche de Rosa avec des dégâts de gerbe persistants, puis utilise Friendzoner pour la repousser hors de portée de ses poings."]]},
"eve":{perd:[["penny","Transforme les petits d'Eve en déclencheurs d'éclaboussure, faisant exploser ses bourses d'or à travers eux pour la toucher tout en nettoyant l'essaim."],["janet","Transperce les petits d'Eve avec ses attaques soniques concentrées, nettoyant l'essaim tout en maintenant la pression sur Eve elle-même."],["max","Esquive les volées d'œufs décalées d'Eve grâce à sa vitesse supérieure, puis son tir rapide nettoie les rejetons avant qu'ils ne s'installent."],["piper","Porte plus loin que la volée d'œufs d'Eve et punit son déchargement lent, la forçant à reculer avant que ses petits n'installent la pression. Faible aussi contre : Sniper"]],bat:[["gene","Reste hors de la portée pleine puissance de Gene pendant que ses petits consomment ses tirs au chargement lent et interceptent sa traction."],["glowy","Contrôle Glowy hors de portée de son rayon pendant que les rejetons saturent ses dégâts mono-cible et installent une pression de poison."],["najia","Force Najia à dépenser son unique munition sur des petits jetables, dont la mort ne peut pas activer Poisonous Protector ."]]},
"fang":{perd:[["colette","Porte plus loin que le coup de pied de Fang avec ses tirs proportionnels, puis Push It l'emporte au loin dès qu'il s'engage dans un plongeon."],["elprimo","Encaisse mieux que Fang au corps-à-corps, absorbant son combo avant que des coups de poing au rechargement plus rapide ne submergent sa série de coups de pied plus lente."],["griff","Punit le plongeon engagé de Fang avec des volées de pièces denses, concentrant leurs dégâts à bout portant pour un lourd burst."],["chester","Explose Fang après son plongeon avec des volées de cloches croissantes, concentrant chaque projectile à bout portant avant qu'il ne décroche."],["clancy","Punit le plongeon de Fang avec une large volée de Super, transformant chaque bille de peinture placée en progression vers ses paliers supérieurs."],["otis","Réduit Fang au silence pendant son plongeon, l'empêchant d'attaquer ou d'utiliser son Super pendant que des volées d'encre continues l'achèvent."],["shelly","Explose Fang à bout portant, le recul du Super coupant sa relance avant qu'il n'enchaîne ses coups de pied rapprochés."],["gale","Refuse le plongeon de Fang par le déplacement forcé : Twister stoppe son Super et le recul le maintient hors de portée de coup de pied."]],bat:[]},
"finx":{perd:[["elprimo","Encaisse mieux que Finx et contourne le ralentissement de projectiles de Time Warp en lui sautant dessus avec son Super pour décharger ses poings."],["gus","Porte plus loin que Finx, pendant que les soins de ses esprits et le bouclier de Spooky absorbent son usure et remportent les échanges de couloir prolongés."],["larry","Lance des doubles explosions par-dessus les murs pendant que Lawrie presse le flanc de Finx, réduisant la sécurité que procure Time Warp."]],bat:[["gigi","Presse Gigi hors de portée de sa rotation, puis revient à sa position antérieure avec ses munitions rendues au moment où elle engage sa téléportation retardée."]]},
